// swift-tools-version: 6.2
//
// TMLCore: what the Track Me Live app and its widget extension share.
//
// - Contracts/ and Tokens/ are symlinks into code/shared (generated by the shared-contracts tooling
//   from the Firestore schema and design-system/tokens.json). They are referenced, never copied.
// - Fonts/: the bundled Gabarito (SIL OFL) and the display type scale, scaled with UIFontMetrics.
// - LiveActivity/: the ActivityAttributes for a share session, used by the app and the widget.
// - Formatting/, Mascots/: small value types both targets need.
//
// Everything here also builds for macOS, so `swift build` and `swift test` run with only the
// Command Line Tools installed. UIKit- and ActivityKit-only code is behind `#if os(iOS)`.
import PackageDescription

let package = Package(
    name: "TMLCore",
    defaultLocalization: "en",
    platforms: [.iOS(.v26), .macOS(.v26)],
    products: [
        .library(name: "TMLCore", targets: ["TMLCore"]),
    ],
    targets: [
        .target(
            name: "TMLCore",
            resources: [.process("Resources")]
        ),
        .testTarget(
            name: "TMLCoreTests",
            dependencies: ["TMLCore"]
        ),
    ],
    swiftLanguageModes: [.v6]
)
